oonlijk karakter. De roman volgt hoe verschillende belangen en ervaringen hun omgang beïnvloeden, terwijl aantrekkingskracht de afstand tussen werkgever en werknemer ingewikkelder maakt.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1618138/tussen-de-regels.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789022566923","key":{"isbn_13":"9789022566923"},"before":null,"after":{"work_id":975100042,"title":"Terugkeer naar Inverness","isbn_13":"9789022566923","isbn_10":"9022566927","language":"nld","publisher":"Meulenhoff Boekerij B.V.","id":975200112}},{"relation":"catalog_edition_metadata","ref":"metadata:9789022566923","key":{"edition_id":"@edition:9789022566923"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/297413/terugkeer-naar-inverness.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://www.bibliotheek.nl/catalogus/titel.362787344.html/terugkeer-naar-inverness/","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000521324_Terugkeer_naar_Inverness_0_0.jpg","checkedAt":"2026-10-31T23:12:24.526Z","sha256":"fa64b5d551fd2dc8c32782ddb8de691c6ac71ee8f9ca40ab63e432bb5b17ed45","bytes":478389,"fact":"Manual title/author/exact edition cover binding, readable published front"},{"reviewNote":"Bureau blurb describes20year reunion/Voyager rather than book2; new summary based on exact library Dragonfly/1745 evidence instead"}],"edition_id":"@edition:9789022566923","work_id":975100042,"bound_author_id":8800014,"bound_title":"Terugkeer naar Inverness","bound_language":"nld","bound_isbn13":"9789022566923","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000521324_Terugkeer_naar_Inv