brengt. Een man met problemen vraagt Elizabeth om hulp en de moordclub raakt betrokken bij het raadsel van een versleutelde code. Elizabeth, Joyce, Ron en Ibrahim moeten uitzoeken wie erachteraan zit. Het vijfde boek over de oudere speurders verbindt hun persoonlijke levens met een dreiging die zich niet laat uitstellen.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/2144139/het-onmogelijke-fortuin.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789464822076","key":{"isbn_13":"9789464822076"},"before":null,"after":{"work_id":975100049,"title":"Hopeloos","isbn_13":"9789464822076","isbn_10":"9464822074","language":"nld","publisher":"April Books","id":975200119}},{"relation":"catalog_edition_metadata","ref":"metadata:9789464822076","key":{"edition_id":"@edition:9789464822076"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1829947/hopeloos.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1829947/hopeloos.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000644321_Hopeloos_0_0.jpg","checkedAt":"2026-10-31T23:12:37.32Z","sha256":"3780bf8c488c04ba0f362c7c970c286af56790d64b2471bf195d4e013ff3a26a","bytes":834864,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789464822076","work_id":975100049,"bound_author_id":975300002,"bound_title":"Hopeloos","bound_language":"nld","bound_isbn13":"9789464822076","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000644321_Hopeloos_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1829947/hopeloos.html"}},{"relation":"catalog_work_des