2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000613050_Stromend_graf_0_0.jpg","checkedAt":"2026-10-31T23:12:43.179Z","sha256":"91c27e34c8a16ed6c6618dfda6533da85a173bbd51bffa4a564728d364f41547","bytes":618417,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":975100052,"language":"nl","bound_author_id":946301088,"text":"Een vader vraagt Cormoran Strike zijn zoon te helpen, die zich heeft aangesloten bij een religieuze organisatie in Norfolk. Achter het vreedzame publieke beeld vermoedt de detective ernstige misstanden. Robin Ellacott gaat undercover om van binnenuit bewijs te verzamelen. Hun zevende zaak draait om de afstand tussen een zorgvuldig opgebouwde reputatie en de ervaringen van mensen die steeds moeilijker aan de gemeenschap kunnen ontsnappen.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1724145/tijdelijke-titel-deel-7-comoran-strike.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789464821307","key":{"isbn_13":"9789464821307"},"before":null,"after":{"work_id":975100053,"title":"Harteloos","isbn_13":"9789464821307","isbn_10":"9464821302","language":"nld","publisher":"April Books","id":975200123}},{"relation":"catalog_edition_metadata","ref":"metadata:9789464821307","key":{"edition_id":"@edition:9789464821307"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1799797/harteloos.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1799797/harteloos.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000628186_Harteloos_0_0.jpg","checkedAt":"2026-10-31T23:12:45.045Z"