rteloos.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789464822052","key":{"isbn_13":"9789464822052"},"before":null,"after":{"work_id":975100054,"title":"Roekeloos","isbn_13":"9789464822052","isbn_10":"9464822058","language":"nld","publisher":"April Books","id":975200124}},{"relation":"catalog_edition_metadata","ref":"metadata:9789464822052","key":{"edition_id":"@edition:9789464822052"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1829946/roekeloos.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1829946/roekeloos.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000644320_Roekeloos_0_0.jpg","checkedAt":"2026-10-31T23:12:46.91Z","sha256":"3a8325de4a7192a32dd043f64cec74739a0183551dbd56435dfac4cae604dbe7","bytes":739371,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789464822052","work_id":975100054,"bound_author_id":975300002,"bound_title":"Roekeloos","bound_language":"nld","bound_isbn13":"9789464822052","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000644320_Roekeloos_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1829946/roekeloos.html"}},{"relation":"catalog_work_descriptions","ref":"description:1910:nl","key":{"work_id":975100054,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1829946/roekeloos.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1829946/roekeloos.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000644320_Roekeloos_0_0.jpg","checkedAt":"2026-10-31T23:12:46.91Z","sha256":"3a8325de4a7192a32dd043f64cec74739a0183551dbd56435dfac4cae604dbe7","bytes":739371,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":975100054,"language":"nl","bound_author_id":975300002,"text":"Winter probeert na een ongelukkig huwelijk opnieuw richting aan haar leven te geven. Op de ranch van de familie Eaton ontmoet ze stierenrijder Theo Silva. Wat begint als een kort contact krijgt onverwachte gevolgen wanneer ze ontdekt dat ze zwanger is. Het vierde Chestnut Springs-boek volgt hun moeizame communicatie en de vraag hoe twee mensen die elkaar nauwelijks kennen verantwoordelijkheid en een mogelijke relatie vormgeven.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1829946/roekeloos.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789493169098","key":{"isbn_13":"9789493169098"},"before":null,"after":{"work_id":928102195,"title":"Wolf Hall","isbn_13":"9789493169098","isbn_10":"949316909X","language":"nld","publisher":"Meridiaan Uitgevers","id":975200125}},{"relation":"catalog_edition_metadata","ref":"metadata:9789493169098","key":{"edition_id":"@edition:9789493169098"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/201724/wolf-hall.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/201724/wolf-hall.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://rozet.nl/catalogus/1982863/","checkedAt":"2026-11-01","fact":"Independent identity/content corr