31/caraval-2-meester-legende.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://cdn.boekhub.overamstel.com/omnifiles/Rainbow_brochure_V24_LR_2.pdf","checkedAt":"2026-11-01","fact":"Independent identity/content corroboration"},{"url":"https://metadata.isbn.nl/ie_fcache/0000621239_Caraval_2_-_Meester_Legende_0_0.jpg","checkedAt":"2026-10-31T23:12:54.204Z","sha256":"a098838652f1b7ff7857c5cee988daff3c2fb39f1650153de3a8a154e0d180dd","bytes":454712,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789041715951","work_id":975100057,"bound_author_id":735,"bound_title":"Meester Legende","bound_language":"nld","bound_isbn13":"9789041715951","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000621239_Caraval_2_-_Meester_Legende_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1778231/caraval-2-meester-legende.html"}},{"relation":"catalog_work_descriptions","ref":"description:2216:nl","key":{"work_id":975100057,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1778231/caraval-2-meester-legende.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1778231/caraval-2-meester-legende.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://cdn.boekhub.overamstel.com/omnifiles/Rainbow_brochure_V24_LR_2.pdf","checkedAt":"2026-11-01","fact":"Independent identity/content corroboration"},{"url":"https://metadata.isbn.nl/ie_fcache/0000621239_Caraval_2_-_Meester_Legende_0_0.jpg","checkedAt":"2026-10-31T23:12:54.204Z","sha256":"a098838652f1b7ff7857c5cee988daff3c2fb39f1650153de3a8a154e0d180dd","bytes":454712,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":975100057,"language":"nl","bound_author_id":735,"text":"Donatella doet opnieuw mee aan een voorstelling van Caraval, ditmaal tijdens een bijzonder feest voor de keizerin. Naast het zichtbare spel heeft ze een eigen opdracht: informatie over haar verdwenen moeder verkrijgen. Daarvoor moet ze de ware identiteit van meester Legende achterhalen. Het vervolg op Caraval maakt haar zoektocht steeds ingewikkelder wanneer nieuwsgierigheid, gevaar en gevoelens voor de raadselachtige spelmeester door elkaar gaan lopen.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1778231/caraval-2-meester-legende.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789041716316","key":{"isbn_13":"9789041716316"},"before":null,"after":{"work_id":975100058,"title":"Finale","isbn_13":"9789041716316","isbn_10":"9041716319","language":"nld","publisher":"Uitgeverij Rainbow bv","id":975200129}},{"relation":"catalog_edition_metadata","ref":"metadata:9789041716316","key":{"edition_id":"@edition:9789041716316"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1934957/finale.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1934957/finale.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://rozet.nl/catalogus/2295073/","checkedAt":"2026-11-01","fact":"Independent identity/content corroboration"},{"url":"https://metadata.isbn.nl/ie_fcache/0000694689_Finale_0_0.jpg","checkedAt":"2026-10-31T23:14:50.205Z","sha256":"63a1e14bb13fbc877a304fe42af8e468ed7fe26d92ee8180ab4d8d55587e615e","bytes":415919,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789041716316","work_id":975100058,"bound_author_id":735,"bound_title":"Finale","bound_language":"nld","bound_isbn13":"9789041716316","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000694689_Finale_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1934957/finale.html"}},{"relation":"catalog_work_descriptions","ref":"description:2219:nl","key":{"work_id":975100058,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1934957/finale.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1934957/finale.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://rozet.nl/catalogus/2295073/","checkedAt":"2026-11-01","fact":"Independent identity/content corroboration"},{"url":"https://metadata.isbn.nl/ie_fcache/0000694689_Finale_0_0.jpg","checkedAt":"2026-10-31T23:14:50.205Z","sha256":"63a1e14bb13fbc877a304fe42af8e468ed7fe26d92ee8180ab4d8d55587e615e","bytes":415919,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":975100058,"language":"nl","bound_author_id":735,"text":"Voor Scarlett en Donatella houdt de onzekerheid niet op wanneer Caraval voorbij is. Hun wereld wordt bedreigd door vrijgekomen machten en de gevolgen van eerdere keuzes. Tella moet bepalen wie zij kan vertrouwen, terwijl ook haar zus een moeilijke opdracht krijgt. Het laatste boek van de trilogie verplaatst de inzet van een georganiseerde voorstelling naar een werkelijkheid waarin liefde, familie en de identiteit van Legende steeds belangrijker worden.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1934957/finale.html","provenance":"original_source_reviewed_summary"}}]'::jsonb;receipt jsonb;r jsonb;p jsonb;k jsonb;expected jsonb;prior jsonb;ids jsonb:='{}';kv record;i integer:=0;n integer;begin
 receipt:=nullif(current_setting('lumiscore.catalog_release_receipt',true),'')::jsonb;
 if receipt->>'project' is distinct from 'hlvujbrmfdlrfxdjwsmb' or receipt->>'batch' is distinct from 'nl079-test-nl-cohort003-03-20261101' or jsonb_typeof(receipt->'rows') is distinct from 'array' or jsonb_array_length(receipt->'rows')<>60 then raise exception 'Exact manifest receipt required';end if;
 for p in select value from jsonb_array_elements(reviewed) loop
  i:=i+1;select count(*) into n from jsonb_array_elements(receipt->'rows')x where x->>'seq'=i::text;
  if n<>1 then raise exception 'Receipt manifest sequence mismatch';end if;
  select x into r from jsonb_array_elements(receipt->'rows')x where x->>'seq'=i::text;
  if r->>'relation' is distinct from p->>'relation' then raise exception 'Receipt manifest relation mismatch';end if;
  k:=p->'key';expected:=p->'after';prior:=p->'before';
  for kv in select * from jsonb_each(expected) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then
    if not ids ? substring(kv.value#>>'{}',2) then raise exception 'Receipt manifest missing parent';end if;
    expected:=jsonb_set(expected,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;
  end loop;
  for kv in select * from jsonb_each(k) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then k:=jsonb_set(k,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;
  end loop;
  if prior<>'null'::jsonb then execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',p->>'relation') into prior using prior;end if;
  execute format('select coalesce(jsonb_object_agg(x.key,x.value),''{}''::jsonb) from jsonb_each(to_jsonb(jsonb_populate_record(null::public.%I,$1))) x where $1 ? x.key',p->>'relation') into expected using expected;
  if r->'key' is distinct from k or r->'before_row' is distinct from prior or jsonb_typeof(r->'after_row') is distinct from 'object' or not coalesce((r->'after_row')@>expected,false) then raise exception 'Receipt differs from exact reviewed manifest';end if;
  if r->'after_row' ? 'id' then ids:=jsonb_set(ids,array[p->>'ref'],r->'after_row'->'id');end if;
 end loop;
end;$manifest_guard$;
do $undo$ declare receipt jsonb;r jsonb;actual jsonb;dep record;n bigint;cols text;begin
 receipt:=nullif(current_setting('lumiscore.catalog_release_receipt',true),'')::jsonb;
 if receipt->>'project' is distinct from 'hlvujbrmfdlrfxdjwsmb' or receipt->>'batch' is distinct from 'nl079-test-nl-cohort003-03-20261101' or jsonb_typeof(receipt->'rows') is distinct from 'array' or jsonb_array_length(receipt->'rows')<>60 then raise exception 'Exact first committed receipt required';end if;
 for r in select value from jsonb_array_elements(receipt->'rows') order by (value->>'seq')::integer desc loop
  if r->>'relation' not in ('authors','works','editions','catalog_work_descriptions','catalog_edition_metadata') then raise exception 'Unreviewed receipt relation';end if;
  execute format('select to_jsonb(t) from public.%I t where to_jsonb(t) @> $1 for update',r->>'relation') into actual using r->'key';
  if actual is null and r->'before_row'='null'::jsonb then continue;end if;
  if actual is not distinct from r->'before_row' then continue;end if;
  if actual is distinct from r->'after_row' then raise exception 'Later legitimate change; recovery refused';end if;
  if r->'before_row'='null'::jsonb then
   for dep in select ns.nspname,c.relname,string_agg(format('(to_jsonb(child)->%L)=($1->%L)',ca.attname,pa.attname),' and ' order by k.ord) predicate
    from pg_constraint f join pg_class c on c.oid=f.conrelid join pg_namespace ns on ns.oid=c.relnamespace
    cross join lateral unnest(f.conkey,f.confkey) with ordinality k(childkey,parentkey,ord)
    join pg_attribute ca on ca.attrelid=f.conrelid and ca.attnum=k.childkey join pg_attribute pa on pa.attrelid=f.confrelid and pa.attnum=k.parentkey
    where f.contype='f' and f.confrelid=to_regclass('public.'||(r->>'relation')) group by f.oid,ns.nspname,c.relname
   loop
    execute format('select count(*) from %I.%I child where %s',dep.nspname,dep.relname,dep.predicate) into n using r->'after_row';
    if n>0 then raise exception 'Later dependency in %.%; recovery refused',dep.nspname,dep.relname;end if;
   end loop;
   execute format('delete from public.%I t where to_jsonb(t) @> $1',r->>'relation') using r->'key';
  else
   select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',key,r->>'relation',key),',') into cols from jsonb_each(r->'before_row') where value is distinct from r->'after_row'->key;
   execute format('update public.%I t set %s where to_jsonb(t) @> $2',r->>'relation',cols) using r->'before_row',r->'key';
  end if;
 end loop;
end;$undo$;commit;
